---刷新剩余时间
function GroceryBaseNodeListCell:RefreshTimeGroup(data)
    local seconds = checkInt(data.nextRefreshLeftSeconds)
    if seconds == 0 then
        seconds = checkInt(data.activityEndTime)
    end
    CfUtils.SetActive(self.TimerGroup, seconds > 0)
    if seconds <= 0 then return end
    
    self:StartTimer()
    CfUtils.FillText(self.TimerTextTime, GroceryUtils.FormatTime(seconds))
    CfUtils.SetUISwitchImage(self.ImgClock, seconds > 86400 and 1 or 2)
end
