--region private
---刷新cell状态
function GroceryBaseNodeListCell:RefreshCellState(data)
    local isSoldOut = GroceryUtils.ProductIsSoldOut(data)
    local isLocked, lockedDesc = GroceryUtils.ProductIsLocked(data)
    local exLock = data.exLock == true

    local isGray = isSoldOut or isLocked or exLock
    CfUtils.SetActive(self.DisableBg, isGray)
    CfUtils.SetActive(self.Lock, isLocked or exLock)
    CfUtils.SetActive(self.SellOutGroup, isSoldOut)

    if isLocked then
        CfUtils.FillText(self.LockText, lockedDesc)
    elseif exLock then
        CfUtils.FillText(self.LockText, data.exLockDesc)
    end
end

---刷新道具
---@param data  table   cell数据
function GroceryBaseNodeListCell:RefreshGoods(data)
    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(checkNumber(data.icon))
    if not vo then return end

    -- icon
    local roleGoods = self.BtnNode:Find("RoleGoods")
    local roleSkill = self.BtnNode:Find("RoleSkill")
    local goodsType = GoodsUtils.GetIdType(vo.id)
    if goodsType == Constants.IDType.CardSkin then
        local imageRoleIcon = roleSkill.transform:Find("ImgRoleIcon")
        CfUtils.SetActive(roleSkill, true)
        CfUtils.SetActive(self.ImgIcon, false)
        CfUtils.SetActive(self.SpinePlayer, false)
        CfUtils.SetActive(self.roleGoods, false)
        CfUtils.SetActive(self.CommonPlayerHeadNodeStub, false)
        CfUtils.FillImage(imageRoleIcon, vo.photoPath)
    elseif GoodsUtils.IsCardType(vo.id) then
        local imageRoleIcon = roleGoods.transform:Find("ImgRoleIcon")
        local imgOccupation = roleGoods.transform:Find("ImgOccupation")
        CfUtils.SetActive(roleGoods, true)
        CfUtils.SetActive(self.ImgIcon, false)
        CfUtils.SetActive(self.SpinePlayer, false)
        CfUtils.SetActive(roleSkill, false)
        CfUtils.SetActive(self.CommonPlayerHeadNodeStub, false)
        CfUtils.FillImage(imageRoleIcon, vo.photoPath)
        CfUtils.SetActive(imgOccupation, vo.type == Constants.IDType.CardSkin)
    elseif goodsType == Constants.IDType.GoodsHeadOrFrame then
        CfUtils.SetActive(roleGoods, false)
        CfUtils.SetActive(self.ImgIcon, false)
        CfUtils.SetActive(self.SpinePlayer, false)
        CfUtils.SetActive(self.CommonPlayerHeadNodeStub, true)
        local headNode = self:GetHeadNode()
        if headNode then
            ---@type CommonPlayerHeadNode
            local headEnv  = CfUtils.GetLuaScr(headNode, "Game.Behaviours.CommonPlayerHeadNode")
            if headEnv then
                --种类区分：1头像2头像框3徽章4主题
                if checkNumber(vo.kind) == 1 then
                    headEnv:FreshHeadIcon(vo.id, true)
                elseif checkNumber(vo.kind) == 2  then
                    headEnv:FreshFrame(vo.id, true)
                end
            end
        end
    else
        CfUtils.SetActive(roleGoods, false)
        CfUtils.SetActive(roleSkill, false)
        CfUtils.SetActive(self.CommonPlayerHeadNodeStub, false)
        CfUtils.SetActive(self.ImgIcon, true)
        CfUtils.FillImage(self.ImgIcon, vo.photoPath)

    end
    
    
    -- name
    local name = vo.name
    if checkInt(data.num) > 1 then
        name = string.format('%s x%d', name, checkInt(data.num))
    end
    CfUtils.FillText(self.TextName, name)

    -- 品质
    CfUtils.SetUISwitchImage(self.GoodQuality, vo.quality)

    -- 星级
    for i = 1, self.Star.childCount do
        local go = self.Star.transform:Find("ImgStar"..i)
        if isNotNull(go) then
            CfUtils.SetActive(go, checkInt(vo.quality) >= i)
        end
    end

    -- 库存
    if checkNumber(data.stock) == -1 then
        CfUtils.SetActive(self.Stock, false)
    else
        CfUtils.SetActive(self.Stock, true)
        CfUtils.FillText(self.StockTextNumber, data.currentStock)
    end
    
    -- 价格
    local currencyVo = GoodsConfMgr:GetInstance():GetGoodsVoById(checkNumber(data.prices[1].currency))
    if currencyVo then
        CfUtils.FillImage(self.PriceImgIcon, currencyVo.photoPath)
        CfUtils.SetActive(self.PriceImgIcon, true)
    end
    CfUtils.FillText(self.PriceText, data.prices[1].current)
    if checkInt(data.prices[1].original) == 0 then
        CfUtils.SetActive(self.DiscountPrice, false)
    else
        CfUtils.SetActive(self.DiscountPrice, true)
        CfUtils.FillText(self.DiscountNumber, data.prices[1].original)
        CfUtils.FillImage(self.DiscountIcon, currencyVo.photoPath)
        CfUtils.SetActive(self.DiscountIcon, true)
    end
    
    -- 标签
    local tabType = checkInt(data.iconId)
    if tabType == TagType.Discount then
        CfUtils.FillText(self.DiscountTxtNumber, string.format('%s<size=18>%%</size>', checkInt(tonumber(data.iconTitle) * 100)))
        CfUtils.SetActive(self.DiscountGroup, true)
        CfUtils.SetActive(self.ActivityTabelGroup, false)
        CfUtils.SetActive(self.TimeLimitGroup, false)
    elseif tabType == TagType.Recommend then
        CfUtils.SetActive(self.DiscountGroup, false)
        CfUtils.SetActive(self.ActivityTabelGroup, true)
        CfUtils.SetActive(self.TimeLimitGroup, false)
    elseif tabType == TagType.All then
        CfUtils.FillText(self.DiscountTxtNumber, string.format('%s<size=18>%%</size>', checkInt(tonumber(data.iconTitle) * 100)))
        CfUtils.SetActive(self.DiscountGroup, true)
        CfUtils.SetActive(self.ActivityTabelGroup, true)
        CfUtils.SetActive(self.TimeLimitGroup, false)
    elseif tabType == TagType.TimeLimit then
        CfUtils.SetActive(self.DiscountGroup, false)
        CfUtils.SetActive(self.ActivityTabelGroup, false)
        CfUtils.SetActive(self.TimeLimitGroup, true)
    elseif tabType == TagType.TimAndRec then
        CfUtils.SetActive(self.DiscountGroup, false)
        CfUtils.SetActive(self.ActivityTabelGroup, true)
        CfUtils.SetActive(self.TimeLimitGroup, true)
    else
        CfUtils.SetActive(self.DiscountGroup, false)
        CfUtils.SetActive(self.ActivityTabelGroup, false)
        CfUtils.SetActive(self.TimeLimitGroup, false)
    end
    
    --特殊类型处理
    local goodsType = GoodsUtils.GetIdType(data.icon)
    if goodsType == Constants.IDType.Equipment then
        CfUtils.SetActive(self.EquipGroup, false)
        CfUtils.SetActive(self.ImgIcon, true)
        CfUtils.SetActive(self.RoleGoods, false)
    elseif goodsType == Constants.IDType.CardSkin or goodsType == Constants.IDType.CharacterCard then
        CfUtils.SetActive(self.EquipGroup, false)
        CfUtils.SetActive(self.ImgIcon, false)
        CfUtils.SetActive(self.RoleGoods, true)
        CfUtils.SetActive(self.ImgOccupation, goodsType == Constants.IDType.CardSkin)
        CfUtils.FillImage(self.ImgRoleIcon, vo.photoPath)
    else
        CfUtils.SetActive(self.EquipGroup, false)
        CfUtils.SetActive(self.RoleGoods, false)
        CfUtils.SetActive(self.ImgIcon, true)
    end
end

---开启定时器
function GroceryBaseNodeListCell:StartTimer()
    self:CloseTimer()

    local seconds = checkInt(self:GetCellData().nextRefreshLeftSeconds)
    if seconds == 0 then
        seconds = checkInt(self:GetCellData().activityEndTime)
    end
    if seconds > 0 then
        local timer = CfUtils.CDTimerAppend(
                1,
                seconds,
                true,
                true,
                function ()
                    local data = self:GetCellData()
                    if isNull(data) then return end
                    
                    local s = checkInt(self:GetCellData().nextRefreshLeftSeconds)
                    if s == 0 then
                        s = checkInt(self:GetCellData().activityEndTime)
                    end
                    CfUtils.FillText(self.TimerTextTime, GroceryUtils.FormatTime(s))
                    CfUtils.SetUISwitchImage(self.ImgClock, s > 86400 and 1 or 2)
                end
        )
        self:SetTimer(timer)
    end
end

--- 关闭定时器
function GroceryBaseNodeListCell:CloseTimer()
    if self:GetTimer() then
        CfUtils.CDTimerRemove(self:GetTimer())
    end
end
